/** Frames de una forma (índice por sourceId). */
export function canonFrames(formId: string): SpriteCanonFrame[] {
  return SPRITE_CANON.forms.find(f => f.form === formId)?.frames ?? [];
}

/** Familia+rol únicos del canon (para Dev Studio). */
export function canonFamilies(): { family: string; roles: string[] }[] {
  const m = new Map<string, Set<string>>();
  for (const f of SPRITE_CANON.forms.flatMap(x => x.frames)) {
    if (!m.has(f.family)) m.set(f.family, new Set());
    m.get(f.family)!.add(f.role);
  }
  return [...m.entries()].map(([family, roles]) => ({ family, roles: [...roles].sort() }));
}
